import { View, Text, Svg, Circle, Path, StyleSheet } from '@react-pdf/renderer';
import { colors, fonts } from '../theme';
import { sanitizeGlyphs } from '../text-sanitize';
import type { ReactNode } from 'react';

export type SeverityLevel = 'none' | 'moderate' | 'significant' | 'data-gap' | 'note';

const palette: Record<SeverityLevel, { bg: string; border: string; dot: string; text: string }> = {
  none: { bg: colors.green50, border: colors.green600, dot: colors.green600, text: colors.green700 },
  moderate: { bg: colors.amber50, border: colors.amber600, dot: colors.amber600, text: colors.amber700 },
  significant: { bg: colors.red50, border: colors.red600, dot: colors.red600, text: colors.red700 },
  'data-gap': { bg: colors.gray100, border: colors.gray500, dot: colors.gray500, text: colors.gray700 },
  note: { bg: colors.blue50, border: colors.blue700, dot: colors.blue700, text: colors.blue700 },
};

const LABEL: Record<SeverityLevel, string> = {
  none: 'NO CONSTRAINT',
  moderate: 'MODERATE CONSTRAINT',
  significant: 'SIGNIFICANT CONSTRAINT',
  'data-gap': 'DATA GAP',
  note: 'NOTE',
};

const s = StyleSheet.create({
  container: {
    flexDirection: 'row',
    alignItems: 'flex-start',
    borderLeftWidth: 3,
    paddingVertical: 10,
    paddingHorizontal: 14,
    marginTop: 2,
    marginBottom: 14,
  },
  icon: {
    marginRight: 8,
    marginTop: 1,
  },
  text: {
    fontSize: 10,
    fontFamily: fonts.sans,
    fontWeight: 700,
    flex: 1,
    lineHeight: 1.45,
  },
});

function DotIcon({ color, size = 10 }: { color: string; size?: number }) {
  return (
    <Svg width={size} height={size} viewBox="0 0 10 10">
      <Circle cx={5} cy={5} r={4.5} fill={color} />
    </Svg>
  );
}

function QuestionIcon({ color, size = 10 }: { color: string; size?: number }) {
  return (
    <Svg width={size} height={size} viewBox="0 0 10 10">
      <Circle cx={5} cy={5} r={4.5} fill={color} />
      <Path d="M4 3.5C4 2.8 4.5 2.3 5 2.3S6 2.8 6 3.5C6 4 5.6 4.3 5.2 4.5C5.1 4.6 5 4.7 5 4.9V5.2" stroke="white" strokeWidth={0.9} fill="none" strokeLinecap="round" />
      <Circle cx={5} cy={6.5} r={0.5} fill="white" />
    </Svg>
  );
}

export interface SeverityBadgeProps {
  level: SeverityLevel;
  /** Optional detail text appended after the severity label with " -- " separator. */
  children?: string;
}

export function SeverityBadge({ level, children }: SeverityBadgeProps) {
  const p = palette[level];
  const label = LABEL[level];
  const detail = children ? ` -- ${sanitizeGlyphs(children)}` : '';
  const Icon = level === 'data-gap' ? QuestionIcon : DotIcon;

  return (
    <View
      style={[
        s.container,
        { backgroundColor: p.bg, borderLeftColor: p.border },
      ]}
      wrap={false}
    >
      <View style={s.icon}>
        <Icon color={p.dot} />
      </View>
      <Text style={[s.text, { color: p.text }]}>
        {`${label}${detail}`}
      </Text>
    </View>
  );
}

