import { View, Text, StyleSheet } from '@react-pdf/renderer';
import { colors, fonts } from '../theme';
import { sanitizeGlyphs } from '../text-sanitize';
import type { ReactNode } from 'react';

export type CalloutVariant = 'insight' | 'action' | 'correction' | 'data-gap' | 'neutral';

const palette: Record<CalloutVariant, { bg: string; border: string }> = {
  insight: { bg: '#EEF4F8', border: colors.steelBlue },
  action: { bg: colors.red50, border: colors.red600 },
  correction: { bg: colors.amber50, border: colors.amber600 },
  'data-gap': { bg: colors.gray100, border: colors.gray600 },
  neutral: { bg: colors.gray50, border: colors.gray400 },
};

const s = StyleSheet.create({
  container: {
    borderLeftWidth: 3,
    paddingVertical: 10,
    paddingHorizontal: 14,
    marginBottom: 14,
  },
  text: {
    fontSize: 9.5,
    color: colors.gray700,
    lineHeight: 1.5,
  },
  labelBold: {
    fontFamily: fonts.sans, fontWeight: 700,
  },
});

export interface CalloutProps {
  variant: CalloutVariant;
  label?: string;
  children: ReactNode;
}

export function Callout({ variant, label, children }: CalloutProps) {
  const p = palette[variant];
  return (
    <View
      style={[s.container, { backgroundColor: p.bg, borderLeftColor: p.border }]}
      wrap={false}
    >
      {typeof children === 'string' ? (
        <Text style={s.text}>
          {label && <Text style={s.labelBold}>{sanitizeGlyphs(label)} </Text>}
          {sanitizeGlyphs(children)}
        </Text>
      ) : (
        children
      )}
    </View>
  );
}
